// TransactionPanel.js
import React from 'react';
import { Paper, Typography, CircularProgress } from '@mui/material';
import { alpha } from '@mui/material/styles';

const TransactionPanel = ({ transactions, onRetryTransaction }) => {
  const handleTransactionClick = (transaction) => {
    if (transaction.status === 'error' && onRetryTransaction) {
      onRetryTransaction(transaction);
    }
  };

  return (
    <Paper sx={{
      p: 2,
      height: 'calc(100vh - 32px)',
      overflowY: 'auto',
    }}>
      <Typography variant="h6" sx={{ mb: 2 }}>
        Ongoing Transactions
      </Typography>
      {transactions.map((transaction) => (
        <Paper
          key={transaction.id}
          sx={{
            p: 2,
            mb: 2,
            backgroundColor: (t) =>
              transaction.status === 'pending' ? alpha(t.palette.warning.main, 0.16) :
              transaction.status === 'completed' ? alpha(t.palette.success.main, 0.16) :
              transaction.status === 'error' ? alpha(t.palette.error.main, 0.16) : 'action.hover',
            cursor: transaction.status === 'error' ? 'pointer' : 'default',
            '&:hover': transaction.status === 'error' ? {
              backgroundColor: (t) => alpha(t.palette.error.main, 0.28),
              transition: 'background-color 0.3s'
            } : {}
          }}
          onClick={() => handleTransactionClick(transaction)}
        >
          <Typography variant="subtitle1">
            {transaction.customerName || 'Anonymous Customer'}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Status: {transaction.status}
            {transaction.status === 'pending' &&
              <CircularProgress size={16} sx={{ ml: 1, color: 'warning.main' }} />
            }
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Total: €{transaction.total.toFixed(2)}
          </Typography>
          {transaction.error && (
            <Typography color="error.main" variant="body2">
              {transaction.error}
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                Click to retry this transaction
              </Typography>
            </Typography>
          )}
        </Paper>
      ))}
    </Paper>
  );
};

export default TransactionPanel;